//! The narrower-branch vectors (`branch_key__*`, `docs/security/private-repos.md` §20, generated by
//! `tools/private-repos-vectors/branch_key.py`), byte for byte with
//! `forge-web/lib/private/branch-key.conformance.test.ts`. Unknown input keys are refused at every
//! depth.

use std::collections::{BTreeMap, BTreeSet};
use std::path::PathBuf;

use serde::{Deserialize, Serialize};
use serde_json::{json, Value};

use super::{
    fold, open_pack, real_values, seal_pack_with, seal_ref_with, sniff_kcv, BranchKey,
    BranchKeys, BranchKeyLetter, BranchRing, Ignored, LetterIn,
};
use crate::private::conformance::{error_json, h32, input, nonce12, StoredDocIn, Vector};
use crate::private::doc::Opened;
use crate::private::members_ref::{self, RefUpdateIn};
use crate::private::{tlv, DocKind, Head};

/// The vector case this harness runs; the rules harness skips it.
pub(crate) const CASE: &str = "branch_key";

fn bytes(s: &str) -> Vec<u8> {
    hex::decode(s).unwrap()
}

fn bkey(s: &str) -> BranchKey {
    BranchKey::from_bytes(h32(s))
}

#[derive(Deserialize, Serialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct LetterJson {
    id: String,
    height: u64,
    owner: String,
    body: Value,
}

#[derive(Deserialize, Serialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct CtxIn {
    letters: Vec<LetterJson>,
    audience: BTreeMap<String, Vec<String>>,
}

#[derive(Deserialize, Serialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct BranchIn {
    op: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    repo_id: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    key: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    keys: Option<Vec<String>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    names: Option<Vec<String>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    gen: Option<u32>,
    #[serde(default, skip_serializing_if = "Option::is_none", rename = "type")]
    kind: Option<DocKind>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    owner_id: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    ref_name: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    new_oid: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    prev_oid: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    force: Option<bool>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    salt: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    nonce: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    context: Option<CtxIn>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    doc: Option<StoredDocIn>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    plain: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    file_id: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    seg_log2: Option<u8>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    sealed: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    size_bytes: Option<u64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    head: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    letters: Option<Vec<LetterJson>>,
}

/// The letters as the fold takes them, and the ignored ones the parse refused.
fn parse_letters(letters: &[LetterJson]) -> (Vec<LetterIn>, Vec<(String, Ignored)>) {
    let mut ok = Vec::new();
    let mut bad = Vec::new();
    for l in letters {
        match BranchKeyLetter::parse(&l.body) {
            Ok(Some(letter)) => ok.push(LetterIn {
                id: l.id.clone(),
                height: l.height,
                letter,
            }),
            Ok(None) => {}
            Err(why) => bad.push((l.id.clone(), why)),
        }
    }
    (ok, bad)
}

fn fold_json(repo_id: &[u8; 32], letters: &[LetterJson]) -> Value {
    let (ok, mut bad) = parse_letters(letters);
    let (branches, ignored) = fold(ok);
    bad.extend(ignored);
    // the reference lists ignored letters in fold order, which is the input's height order
    let order: BTreeMap<&str, (u64, &str)> = letters
        .iter()
        .map(|l| (l.id.as_str(), (l.height, l.id.as_str())))
        .collect();
    bad.sort_by_key(|(id, _)| order[id.as_str()]);
    let out: Vec<Value> = branches
        .values()
        .map(|b| {
            let issued: serde_json::Map<String, Value> = b
                .issued_at
                .iter()
                .enumerate()
                .map(|(g, h)| (g.to_string(), json!(h)))
                .collect();
            let kcvs: Vec<String> = b
                .keys()
                .iter()
                .enumerate()
                .map(|(g, k)| {
                    hex::encode(BranchKeys::derive(repo_id, u32::try_from(g).unwrap(), k).kcv4())
                })
                .collect();
            json!({
                "name": b.name,
                "group": b.audience.group.map(crate::env::Group::as_str),
                "people": b.audience.also,
                "issuedAt": issued,
                "letters": b.letters,
                "holders": b.holders,
                "kcvs": kcvs,
                "gen": b.gen(),
            })
        })
        .collect();
    let ignored: Vec<Value> = bad
        .iter()
        .map(|(id, why)| json!({ "id": id, "reason": why }))
        .collect();
    json!({ "branches": out, "ignored": ignored })
}

fn run(v: &Vector) -> Value {
    let i: BranchIn = input(v);
    let repo_id = i.repo_id.as_deref().map(h32);
    match i.op.as_str() {
        "kdf" => {
            let k = BranchKeys::derive(&repo_id.unwrap(), 0, &bkey(i.key.as_deref().unwrap()));
            let [prk, ref_key] = k.raw_subkeys_for_vectors();
            let hashes: Vec<String> = i
                .names
                .unwrap()
                .iter()
                .map(|n| hex::encode(k.ref_name_hash(n)))
                .collect();
            json!({
                "kcv": hex::encode(k.kcv()),
                "prk": hex::encode(prk),
                "refKey": hex::encode(ref_key),
                "refNameHashes": hashes,
            })
        }
        "seal" => {
            let gen = i.gen.unwrap();
            let k = BranchKeys::derive(&repo_id.unwrap(), gen, &bkey(i.key.as_deref().unwrap()));
            let owner = h32(i.owner_id.as_deref().unwrap());
            let new = bytes(i.new_oid.as_deref().unwrap());
            let prev = i.prev_oid.as_deref().map(bytes);
            let input = RefUpdateIn {
                kind: i.kind.unwrap(),
                name: i.ref_name.as_deref().unwrap(),
                new_oid: &new,
                prev_oid: prev.as_deref(),
                force: i.force.unwrap(),
            };
            let salt = h32(i.salt.as_deref().unwrap());
            let sealed =
                match seal_ref_with(&k, owner, &input, salt, nonce12(i.nonce.as_deref().unwrap())) {
                    Ok(s) => s,
                    Err(e) => return error_json(&e),
                };
            let (header, fields) = members_ref::header_and_fields(
                k.ref_name_hash(input.name),
                gen,
                owner,
                &input,
                &salt,
            )
            .unwrap();
            let mut doc = json!({
                "epoch": sealed.epoch,
                "refNameHash": hex::encode(sealed.ref_name_hash),
                "newOid": hex::encode(&sealed.new_oid),
                "force": sealed.force,
            });
            if let Some(p) = &sealed.prev_oid {
                doc["prevOid"] = json!(hex::encode(p));
            }
            json!({
                "doc": doc,
                "tlv": hex::encode(tlv::encode(&fields)),
                "ad": hex::encode(header.ad_in(k.repo_id(), super::V6).unwrap()),
                "enc": hex::encode(&sealed.enc),
            })
        }
        "open" => {
            let repo_id = repo_id.unwrap();
            let ctx = i.context.unwrap();
            let (ok, _) = parse_letters(&ctx.letters);
            let audience = ctx.audience;
            let ring = BranchRing::new(&repo_id, fold(ok), |b| {
                audience
                    .get(&b.name)
                    .into_iter()
                    .flatten()
                    .map(|h| h32(h))
                    .collect::<BTreeSet<_>>()
            });
            let (header, enc) = i.doc.unwrap().split();
            match ring.open(&header, &enc) {
                Opened::Readable(f) => {
                    let r = real_values(&header, &f).expect("checked by open");
                    let mut out = json!({ "name": r.name, "newOid": hex::encode(&r.new_oid) });
                    if let Some(p) = &r.prev_oid {
                        out["prevOid"] = json!(hex::encode(p));
                    }
                    let alerts: Vec<Value> = r
                        .alerts
                        .iter()
                        .map(|a| json!({ "field": a.field, "kind": a.kind }))
                        .collect();
                    json!({
                        "status": "readable",
                        "ref": out,
                        "alerts": alerts,
                        "branch": r.name,
                        "gen": header.epoch,
                    })
                }
                Opened::Unreadable(u) => json!({ "status": "unreadable", "reason": u }),
                Opened::Malformed => json!({ "status": "malformed" }),
            }
        }
        "packSeal" => {
            let k = BranchKeys::derive(&repo_id.unwrap(), 0, &bkey(i.key.as_deref().unwrap()));
            let file_id: [u8; 16] = bytes(i.file_id.as_deref().unwrap()).try_into().unwrap();
            let sealed = seal_pack_with(
                &k,
                &bytes(i.plain.as_deref().unwrap()),
                &file_id,
                i.seg_log2.unwrap(),
            )
            .unwrap();
            let mut out = json!({
                "header": hex::encode(&sealed[..36]),
                "sha256": hex::encode(crate::private::keys::sha256(&sealed)),
            });
            if v.expected.get("sealed").is_some() {
                out["sealed"] = json!(hex::encode(&sealed));
            }
            out
        }
        "packOpen" => {
            let repo_id = repo_id.unwrap();
            let keys: Vec<BranchKeys> = i
                .keys
                .unwrap()
                .iter()
                .map(|k| BranchKeys::derive(&repo_id, 0, &bkey(k)))
                .collect();
            let sealed = bytes(i.sealed.as_deref().unwrap());
            match open_pack(&sealed, i.size_bytes.unwrap(), &keys) {
                Ok(p) => json!({ "plain": hex::encode(p) }),
                Err(e) => error_json(&e),
            }
        }
        "sniff" => {
            let head = bytes(i.head.as_deref().unwrap());
            if let Some(kcv) = sniff_kcv(&head) {
                return json!({ "kind": "branch", "kcv": hex::encode(kcv) });
            }
            match crate::private::sniff(&head) {
                Head::Plain => json!({ "kind": "plain" }),
                Head::Short => json!({ "kind": "short" }),
                Head::Sealed { epoch } => json!({ "kind": "sealed", "epoch": epoch }),
                Head::OtherVersion(3) => json!({ "kind": "short" }),
                Head::OtherVersion(version) => json!({ "kind": "otherVersion", "version": version }),
            }
        }
        "fold" => fold_json(&repo_id.unwrap(), &i.letters.unwrap()),
        other => panic!("vector `{}`: branch_key op `{other}`", v.name),
    }
}

#[test]
fn branch_key_conformance_vectors() {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../forge-contracts/vectors");
    let mut files: Vec<PathBuf> = std::fs::read_dir(&dir)
        .expect("read vectors dir")
        .map(|e| e.unwrap().path())
        .filter(|p| {
            p.file_name()
                .and_then(|n| n.to_str())
                .is_some_and(|n| n.starts_with(&format!("{CASE}__")))
        })
        .collect();
    files.sort();
    let mut ran = 0usize;
    for path in &files {
        let v: Vector = serde_json::from_slice(&std::fs::read(path).unwrap())
            .unwrap_or_else(|e| panic!("parse {}: {e}", path.display()));
        assert_eq!(v.rules, "v2", "{}", path.display());
        assert_eq!(run(&v), v.expected, "vector `{}`", v.name);
        ran += 1;
    }
    assert!(ran >= 52, "ran {ran} branch_key vectors");
}
